// ── Capa 1: Conciliación EXACTA ────────────────────────────────────────────
// Lee el payload del Webhook (body). Match exacto = mismo monto + misma
// referencia; respaldo por mismo monto + misma fecha. Signos ya normalizados
// por la app (cobranza/abono +, pago/cargo −).

const src = $('Webhook').first().json;
const payload = src.body ?? src;

const internos = payload.registros_internos ?? [];
const bancarios = payload.movimientos_bancarios ?? [];

const cents = (m) => Math.round(Number(m) * 100);
const normRef = (r) => String(r ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const idxPorRef = new Map();
const idxPorFecha = new Map();
const push = (map, k, v) => {
  if (!map.has(k)) map.set(k, []);
  map.get(k).push(v);
};
bancarios.forEach((b, j) => {
  const c = cents(b.monto);
  const ref = normRef(b.referencia_banco);
  if (ref) push(idxPorRef, `${c}|${ref}`, j);
  push(idxPorFecha, `${c}|${b.fecha}`, j);
});

const bancUsado = new Set();
const intUsado = new Set();
const matches = [];

const tomarLibre = (lista) => {
  if (!lista) return -1;
  for (const j of lista) if (!bancUsado.has(j)) return j;
  return -1;
};
const registrar = (i, j) => {
  intUsado.add(i);
  bancUsado.add(j);
  matches.push({
    ids_internos: [internos[i].id_interno],
    ids_movimientos: [bancarios[j].id_movimiento],
    metodo: 'exacta',
    confianza: null,
    diferencia_monto: 0,
    categoria_diferencia: null,
    justificacion: null,
    estado_revision: 'auto',
  });
};

// Pass 1: monto + referencia (ID de pago)
internos.forEach((it, i) => {
  const ref = normRef(it.referencia);
  if (!ref) return;
  const j = tomarLibre(idxPorRef.get(`${cents(it.monto)}|${ref}`));
  if (j !== -1) registrar(i, j);
});
// Pass 2: monto + fecha
internos.forEach((it, i) => {
  if (intUsado.has(i)) return;
  const j = tomarLibre(idxPorFecha.get(`${cents(it.monto)}|${it.fecha}`));
  if (j !== -1) registrar(i, j);
});

return [{
  json: {
    job_id: payload.job_id,
    metadata: payload.metadata,
    config: payload.config,
    total_internos: internos.length,
    total_bancarios: bancarios.length,
    matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Capa 2: Conciliación DIFUSA (tolerancias + coincidencia de nombre) ─────
// Toma los pendientes de la capa exacta y concilia por cercanía de monto y
// fecha, EXIGIENDO además al menos una palabra en común entre la contraparte
// (interno) y la glosa (banco). Diferencia de monto tolerada =
// max(tolerancia_monto_abs, |monto|*pct). Fecha tolerada = tolerancia_dias.

const prev = $json;
const { job_id, metadata, config, total_internos, total_bancarios } = prev;
const matches = [...prev.matches];
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];

const tolAbs = Number(config?.tolerancia_monto_abs ?? 0);
const tolPct = Number(config?.tolerancia_monto_pct ?? 0);
const tolDias = Number(config?.tolerancia_dias ?? 0);

const dias = (a, b) => Math.abs((Date.parse(a) - Date.parse(b)) / 86400000);

// Tokenizador: MAYÚSCULAS sin acentos, palabras de >=3 letras, sin términos
// bancarios genéricos.
const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toUpperCase()
    .split(/[^A-Z0-9]+/)
    .filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const setB = new Set(palabras(b));
  return [...new Set(palabras(a).filter((w) => setB.has(w)))];
};

const bancUsado = new Set();
const intUsado = new Set();

internos.forEach((it, i) => {
  for (let j = 0; j < bancarios.length; j++) {
    if (bancUsado.has(j)) continue;
    const bc = bancarios[j];
    if (Math.sign(it.monto) !== Math.sign(bc.monto)) continue;
    const dif = Number((it.monto - bc.monto).toFixed(2));
    const tol = Math.max(tolAbs, Math.abs(it.monto) * (tolPct / 100));
    if (Math.abs(dif) > tol) continue;
    if (dias(it.fecha, bc.fecha) > tolDias) continue;
    const comunes = comunesEntre(it.contraparte, bc.glosa);
    if (comunes.length === 0) continue; // exige coincidencia de nombre
    matches.push({
      ids_internos: [it.id_interno],
      ids_movimientos: [bc.id_movimiento],
      metodo: 'difusa',
      confianza: null,
      diferencia_monto: dif,
      categoria_diferencia: Math.abs(dif) > 0 ? 'comision_bancaria' : null,
      justificacion:
        Math.abs(dif) > 0
          ? `Coincidencia por nombre (${comunes.join(', ')}); diferencia de ${dif.toFixed(2)} compatible con comisión bancaria.`
          : `Coincidencia por nombre (${comunes.join(', ')}).`,
      estado_revision: 'auto',
    });
    intUsado.add(i);
    bancUsado.add(j);
    break;
  }
});

return [{
  json: {
    job_id,
    metadata,
    config,
    total_internos,
    total_bancarios,
    matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Capa 2.5: AGRUPACIÓN 1:N / N:1 (subset-sum) ────────────────────────────
// Un depósito bancario que agrupa varios pagos internos (o un pago dividido en
// varios movimientos). Se acota fuerte para precisión: COINCIDENCIA DE NOMBRE
// OBLIGATORIA (cada miembro comparte >=1 palabra con el objetivo), suma casi
// EXACTA, grupo pequeño (<= max_combinacion), en ventana de fecha. Se proponen
// como SUGERENCIAS (estado 'pendiente') para revisión humana. Va entre Difusa y
// la capa de IA.

const prev = $json;
const { job_id, metadata, config, total_internos, total_bancarios } = prev;
const matches = [...prev.matches];
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];

const tolSum = Math.min(Number(config?.tolerancia_monto_abs ?? 5), 0.5);
const ventana = Number(config?.ventana_ia_dias ?? 30);
const maxTam = Number(config?.max_combinacion ?? 3);

const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase()
    .split(/[^A-Z0-9]+/).filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const B = new Set(palabras(b));
  return palabras(a).filter((w) => B.has(w));
};
const dias = (a, b) => Math.abs((Date.parse(a) - Date.parse(b)) / 86400000);

function* combinaciones(items, maxT) {
  const n = items.length;
  function* rec(inicio, acc) {
    if (acc.length >= 2) yield acc.slice();
    if (acc.length >= maxT) return;
    for (let i = inicio; i < n; i++) { acc.push(items[i]); yield* rec(i + 1, acc); acc.pop(); }
  }
  yield* rec(0, []);
}

function agrupar(unos, muchos) {
  const usados = new Set();
  const grupos = [];
  for (const t of unos) {
    // Prefiltro por nombre: cada candidato debe compartir >=1 palabra con el
    // objetivo. Así toda combinación es coherente por construcción (sin esto se
    // agrupaban personas sin relación cuya suma cuadraba por casualidad).
    const cands = muchos
      .filter((m) => !usados.has(m.id) && Math.sign(m.monto) === Math.sign(t.monto) &&
        Math.abs(m.monto) <= Math.abs(t.monto) + tolSum && dias(t.fecha, m.fecha) <= ventana &&
        comunesEntre(m.texto, t.texto).length > 0)
      .sort((a, b) => dias(t.fecha, a.fecha) - dias(t.fecha, b.fecha))
      .slice(0, 12);
    if (cands.length < 2) continue;
    let mejor = null;
    for (const combo of combinaciones(cands, maxTam)) {
      const suma = combo.reduce((s, x) => s + x.monto, 0);
      if (Math.abs(suma - t.monto) > tolSum) continue;
      const dif = Number((suma - t.monto).toFixed(2));
      // Todos los miembros ya comparten nombre: preferir menos elementos y, a
      // igualdad, menor diferencia de monto.
      if (!mejor || combo.length < mejor.combo.length ||
          (combo.length === mejor.combo.length && Math.abs(dif) < Math.abs(mejor.dif))) {
        mejor = { combo, dif };
      }
    }
    if (!mejor) continue;
    grupos.push({ targetId: t.id, ids: mejor.combo.map((x) => x.id), dif: mejor.dif, n: mejor.combo.length });
    for (const x of mejor.combo) usados.add(x.id);
  }
  return grupos;
}

const itemInt = (r) => ({ id: r.id_interno, monto: r.monto, fecha: r.fecha, texto: r.contraparte ?? r.descripcion ?? null });
const itemBanc = (m) => ({ id: m.id_movimiento, monto: m.monto, fecha: m.fecha, texto: m.glosa ?? null });

const usadoInt = new Set();
const usadoBanc = new Set();

// 1 banco : N internos
for (const g of agrupar(bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)).map(itemBanc),
                        internos.filter((r) => !usadoInt.has(r.id_interno)).map(itemInt))) {
  matches.push({
    ids_internos: g.ids, ids_movimientos: [g.targetId], metodo: "ia", confianza: null,
    diferencia_monto: g.dif, categoria_diferencia: "agrupacion_1aN",
    justificacion: `Agrupación: ${g.n} registros internos suman el depósito (dif. ${g.dif}).`,
    estado_revision: "pendiente",
  });
  usadoBanc.add(g.targetId);
  for (const id of g.ids) usadoInt.add(id);
}
// 1 interno : N bancos
for (const g of agrupar(internos.filter((r) => !usadoInt.has(r.id_interno)).map(itemInt),
                        bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)).map(itemBanc))) {
  matches.push({
    ids_internos: [g.targetId], ids_movimientos: g.ids, metodo: "ia", confianza: null,
    diferencia_monto: -g.dif, categoria_diferencia: "agrupacion_1aN",
    justificacion: `Agrupación: el pago se refleja en ${g.n} movimientos bancarios (dif. ${-g.dif}).`,
    estado_revision: "pendiente",
  });
  usadoInt.add(g.targetId);
  for (const id of g.ids) usadoBanc.add(id);
}

return [{
  json: {
    job_id, metadata, config, total_internos, total_bancarios, matches,
    pendientes_internos: internos.filter((r) => !usadoInt.has(r.id_interno)),
    pendientes_bancarios: bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)),
  },
}];

// ── Etapa clave: GENERACIÓN DE CANDIDATOS + prompt para el LLM ─────────────
// Prepara, por cada registro interno pendiente, una lista corta (top-K) de los
// movimientos bancarios más relevantes, con features y score (blocking +
// scoring). El LLM luego solo ADJUDICA sobre esta shortlist (elige el mejor o
// "ninguno") — no busca a ciegas. Nombra este nodo exactamente "Candidatos IA"
// (el nodo de parseo lo referencia por ese nombre).

const prev = $json;
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];
const cfg = prev.config ?? {};
// Few-shot dinámico: ejemplos de decisiones humanas previas (los arma el backend
// y viajan en el payload original del Webhook).
const wh = $('Webhook').first().json;
const ejemplos = ((wh.body ?? wh).ejemplos_aprendizaje) ?? [];
const tolIa = Number(cfg.tolerancia_ia_monto ?? 10);
const K = Number(cfg.top_k_candidatos ?? 3);
const ventana = Number(cfg.ventana_ia_dias ?? 30); // ventana de fecha amplia para IA

// ── Utilidades de matching ────────────────────────────────────────────────
const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase()
    .split(/[^A-Z0-9]+/).filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const B = new Set(palabras(b));
  return [...new Set(palabras(a).filter((w) => B.has(w)))];
};
const jaccard = (a, b) => {
  const A = new Set(palabras(a)), B = new Set(palabras(b));
  if (!A.size && !B.size) return 0;
  let i = 0; for (const t of A) if (B.has(t)) i++;
  const u = new Set([...A, ...B]).size; return u ? i / u : 0;
};
// Referencias: token alfanumérico con >=1 letra y >=1 dígito, longitud >=4.
// Se extraen del campo de referencia y del texto libre (glosa/descripción).
const esRefToken = (t) => t.length >= 4 && /[A-Z]/.test(t) && /[0-9]/.test(t);
const refsDeTexto = (texto, set) => {
  for (const tok of String(texto ?? "").toUpperCase().split(/[^A-Z0-9]+/)) if (esRefToken(tok)) set.add(tok);
};
const refCampo = (ref, set) => {
  const c = String(ref ?? "").toUpperCase().replace(/[^A-Z0-9]/g, ""); if (esRefToken(c)) set.add(c);
};
const refsInterno = (it) => { const s = new Set(); refCampo(it.referencia, s); refsDeTexto(it.descripcion, s); return s; };
const refsBanco = (bc) => { const s = new Set(); refCampo(bc.referencia_banco, s); refsDeTexto(bc.glosa, s); return s; };
const intersecta = (a, b) => { for (const x of a) if (b.has(x)) return true; return false; };
const dias = (a, b) => Math.abs((Date.parse(a) - Date.parse(b)) / 86400000);
const catProb = (d) =>
  d < 0.005 ? "diferencia_temporal" : d <= 10 ? "comision_bancaria" : "requiere_investigacion";

const shortlists = [];
const refsBc = bancarios.map((bc) => refsBanco(bc));

for (const it of internos) {
  const refsIt = refsInterno(it);
  const cands = [];
  for (let bi = 0; bi < bancarios.length; bi++) {
    const bc = bancarios[bi];
    if (Math.sign(it.monto) !== Math.sign(bc.monto)) continue;
    const d = dias(it.fecha, bc.fecha);
    if (d > ventana) continue;
    const difAbs = Math.abs(it.monto - bc.monto);
    const comparteRef = intersecta(refsIt, refsBc[bi]);
    const comunes = comunesEntre(it.contraparte, bc.glosa);
    // Si comparte referencia, es candidato aunque no comparta nombre ni esté en
    // la banda de monto. Si no, exige nombre Y banda de monto.
    if (!comparteRef) {
      if (!comunes.length) continue;
      if (difAbs > tolIa) continue;
    }
    const sim = jaccard(it.contraparte, bc.glosa);
    const cercM = 1 - Math.min(difAbs / (tolIa || 1), 1);
    const cercF = 1 - Math.min(d / (ventana || 1), 1);
    const score = Number(Math.min(1, 0.5 * sim + 0.3 * cercM + 0.2 * cercF + (comparteRef ? 0.4 : 0)).toFixed(3));
    cands.push({
      id_movimiento: bc.id_movimiento,
      glosa: bc.glosa ?? "",
      fecha: bc.fecha,
      monto: bc.monto,
      dif: Number((it.monto - bc.monto).toFixed(2)),
      dias: d,
      palabras_comunes: comunes,
      comparte_ref: comparteRef,
      score,
      categoria_probable: catProb(difAbs),
    });
  }
  cands.sort((a, b) => b.score - a.score);
  if (cands.length) {
    shortlists.push({
      id_interno: it.id_interno,
      fecha: it.fecha,
      monto: it.monto,
      nombre: it.contraparte ?? it.descripcion ?? "",
      referencia: it.referencia ?? "",
      candidatos: cands.slice(0, K),
    });
  }
}

// ── Prompt para el LLM (adjudicación) ─────────────────────────────────────
const system = [
  "Eres un experto en conciliación bancaria peruana. Para cada REGISTRO INTERNO",
  "recibes una lista corta de CANDIDATOS bancarios ya pre-seleccionados (por",
  "monto, fecha y nombre), con features y un score. Tu tarea es ADJUDICAR: por",
  "cada registro interno elige el candidato que corresponde a la MISMA",
  'transacción real, o "ninguno" si ninguno es convincente.',
  "",
  "Reglas:",
  "- Elige a lo sumo UN candidato por registro interno (usa su id_movimiento).",
  "- Un movimiento bancario no debe usarse para dos registros distintos.",
  "- Debe haber correspondencia de identidad (nombre) y coherencia de monto/fecha.",
  '- Si dudas, responde "ninguno". Prefiere precisión sobre cobertura.',
  "- La fecha puede diferir bastante (el depósito llega tarde); prioriza monto y",
  "  nombre por sobre la cercanía de fecha.",
  "- Clasifica la diferencia en `categoria`, una de: comision_bancaria,",
  "  pago_parcial, diferencia_temporal, diferencia_moneda, redondeo,",
  "  requiere_investigacion.",
  "",
  'Responde ÚNICAMENTE JSON: {"pares":[{"id_interno":"...","id_movimiento":"...',
  ' o ninguno","confianza":0.0,"categoria":"...","justificacion":"..."}]}.',
  "Sin texto fuera del JSON, sin ```.",
].join("\n");

// Bloque few-shot: patrones aprendidos de decisiones humanas reales. Los nombres
// cambian entre períodos; lo que se aprende es CUÁNTO tolera la empresa en
// monto/fecha/nombre y cuándo rechaza. Formato: monto · nombre · fecha.
const fewShot = ejemplos.length
  ? [
      "",
      "DECISIONES HUMANAS PREVIAS (aprende el criterio de esta empresa; fíjate en el",
      "patrón, no en los nombres puntuales):",
      ...ejemplos.map(
        (e) =>
          `- [${String(e.decision).toUpperCase()}] interno {${e.interno}} ↔ banco {${e.banco}}` +
          (e.categoria ? ` (${e.categoria})` : ""),
      ),
      "Calibra tu criterio con estos ejemplos (p. ej. si suelen ACEPTAR pese a una",
      "comisión, o RECHAZAR cuando el nombre no calza pese a montos iguales). No los",
      "copies a ciegas: aplícalos solo cuando el caso sea análogo.",
    ].join("\n")
  : "";
const systemFinal = system + fewShot;

const user = `Tolerancias: ${JSON.stringify(cfg)}\n\nCandidatos por registro interno:\n${JSON.stringify(shortlists)}`;

const ia_body = {
  model: "claude-opus-4-8",
  max_tokens: 8000,
  system: systemFinal,
  messages: [{ role: "user", content: user }],
  output_config: {
    format: {
      type: "json_schema",
      schema: {
        type: "object",
        additionalProperties: false,
        required: ["pares"],
        properties: {
          pares: {
            type: "array",
            items: {
              type: "object",
              additionalProperties: false,
              required: ["id_interno", "id_movimiento", "confianza", "categoria", "justificacion"],
              properties: {
                id_interno: { type: "string" },
                id_movimiento: { type: "string" },
                confianza: { type: "number" },
                categoria: { type: "string" },
                justificacion: { type: "string" },
              },
            },
          },
        },
      },
    },
  },
};

return [{
  json: {
    job_id: prev.job_id,
    metadata: prev.metadata,
    config: prev.config,
    total_internos: prev.total_internos,
    total_bancarios: prev.total_bancarios,
    matches: prev.matches,
    pendientes_internos: internos,
    pendientes_bancarios: bancarios,
    shortlists, // para validar la respuesta del LLM
    ejemplos_aprendizaje: ejemplos, // trazabilidad del few-shot usado
    ia_body, // nodo HTTP Request (alternativa)
    ia_system: systemFinal, // nodo AI Agent (systemMessage)
    ia_user: user, // nodo AI Agent (prompt)
  },
}];

// ── IA (2/2): Adjudicar la respuesta del LLM validando contra candidatos ───
// El LLM eligió, por registro interno, un candidato de la shortlist (o
// "ninguno"). Aquí se valida que el id elegido REALMENTE estaba entre los
// candidatos de ese interno (anti-alucinación fuerte), se fuerza 1-a-1 y se
// agregan como método "ia". Mantiene la misma forma de salida para "Ensamblar".

// El estado (shortlists, pendientes, matches, config) viene de "Candidatos IA".
const prep = $('Candidatos IA').first().json;
const matches = [...(prep.matches ?? [])];
const internos = prep.pendientes_internos ?? [];
const bancarios = prep.pendientes_bancarios ?? [];
const shortlists = prep.shortlists ?? [];
const umbral = Number(prep.config?.umbral_confianza_auto ?? 0.95);

// Mapa id_interno -> { candidatos válidos, categoria por movimiento }.
const candPorInterno = new Map();
for (const s of shortlists) {
  const set = new Set();
  const catPorMov = new Map();
  for (const c of s.candidatos ?? []) {
    set.add(c.id_movimiento);
    catPorMov.set(c.id_movimiento, c.categoria_probable);
  }
  candPorInterno.set(s.id_interno, { set, catPorMov });
}

// Extraer los pares de la respuesta del LLM. Se cubren todas las formas:
//  - AI Agent con Output Parser -> $json.output ya es objeto/array
//  - AI Agent sin parser        -> $json.output es texto (JSON)
//  - HTTP Anthropic             -> $json.content[] con bloque type=text
//  - OpenAI (chat completions)  -> $json.choices[0].message.content
const resp = $json;
let parsed = null;

const directo = resp.output ?? resp.json ?? null;
if (directo && typeof directo === "object") {
  parsed = directo; // ya viene parseado (Output Parser)
} else {
  let texto = "";
  if (Array.isArray(resp.content)) {
    const tb = resp.content.find((b) => b && b.type === "text");
    texto = tb ? tb.text : "";
  } else {
    texto =
      resp.output ??
      resp.text ??
      (resp.choices && resp.choices[0] && resp.choices[0].message
        ? resp.choices[0].message.content
        : "") ??
      "";
  }
  texto = String(texto).trim()
    .replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
  try {
    parsed = JSON.parse(texto);
  } catch (e) {
    parsed = null;
  }
}

const pares =
  Array.isArray(parsed) ? parsed : parsed && parsed.pares ? parsed.pares : [];

const idxInt = new Map(internos.map((r, i) => [r.id_interno, i]));
const idxBanc = new Map(bancarios.map((m, j) => [m.id_movimiento, j]));
const intUsado = new Set();
const bancUsado = new Set();

for (const p of pares) {
  const idI = p.id_interno;
  const idB = p.id_movimiento;
  if (!idB || idB === "ninguno") continue;
  const cand = candPorInterno.get(idI);
  if (!cand || !cand.set.has(idB)) continue; // debía estar entre los candidatos
  const i = idxInt.get(idI);
  const j = idxBanc.get(idB);
  if (i == null || j == null || intUsado.has(i) || bancUsado.has(j)) continue;
  const it = internos[i], bc = bancarios[j];
  const confianza = Math.max(0, Math.min(1, Number(p.confianza ?? 0.8)));
  matches.push({
    ids_internos: [idI],
    ids_movimientos: [idB],
    metodo: "ia",
    confianza,
    diferencia_monto: Number((it.monto - bc.monto).toFixed(2)),
    categoria_diferencia: p.categoria ?? cand.catPorMov.get(idB) ?? "requiere_investigacion",
    justificacion: p.justificacion ?? "Sugerido por IA.",
    estado_revision: confianza >= umbral ? "auto" : "pendiente",
  });
  intUsado.add(i);
  bancUsado.add(j);
}

return [{
  json: {
    job_id: prep.job_id,
    metadata: prep.metadata,
    config: prep.config,
    total_internos: prep.total_internos,
    total_bancarios: prep.total_bancarios,
    matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Ensamblar RESULTADO (§7.3) + cuadre de saldos ──────────────────────────
// Junta todos los matches, arma resumen y no_conciliados desde los pendientes,
// y calcula el cuadre bancario a partir de los saldos. Devuelve el cuerpo listo
// para el UPDATE a Supabase (un solo campo JSONB `resultado`).

const prev = $json;
const { job_id, metadata, total_internos, total_bancarios } = prev;
const matches = prev.matches ?? [];
const pendInt = prev.pendientes_internos ?? [];
const pendBanc = prev.pendientes_bancarios ?? [];

const cuenta = (m) => matches.filter((x) => x.metodo === m).length;

const no_conciliados = [
  ...pendInt.map((it) => ({
    id: it.id_interno,
    lado: 'interno',
    categoria: 'requiere_investigacion',
    sugerencia: it.monto >= 0 ? 'Posible depósito en tránsito' : 'Posible cheque no cobrado',
  })),
  ...pendBanc.map((bc) => ({
    id: bc.id_movimiento,
    lado: 'bancario',
    categoria: 'ajuste_requerido',
    sugerencia: 'Cargo/abono no registrado en libros',
  })),
];

// Cuadre bancario.
const saldos = metadata?.saldos ?? {};
const r2 = (n) => Number(Number(n).toFixed(2));
const saldoExtractoFinal = Number(saldos.saldo_extracto_final ?? 0);
const depositosEnTransito = pendInt.reduce((a, it) => a + (it.monto > 0 ? it.monto : 0), 0);
const chequesNoCobrados = pendInt.reduce((a, it) => a + (it.monto < 0 ? it.monto : 0), 0);
const cargosNoRegistrados = pendBanc.reduce((a, bc) => a + (bc.monto < 0 ? bc.monto : 0), 0);
const saldoBancoAjustado =
  saldoExtractoFinal + depositosEnTransito + chequesNoCobrados + cargosNoRegistrados;
const saldoLibros = Number(saldos.saldo_libros_final ?? 0);

const resultado = {
  resumen: {
    total_internos,
    total_bancarios,
    conciliados_exactos: cuenta('exacta'),
    conciliados_difusos: cuenta('difusa'),
    sugeridos_ia: cuenta('ia'),
    sin_conciliar_internos: pendInt.length,
    sin_conciliar_bancarios: pendBanc.length,
  },
  matches,
  no_conciliados,
  cuadre: {
    saldo_extracto_final: r2(saldoExtractoFinal),
    depositos_en_transito: r2(depositosEnTransito),
    cheques_no_cobrados: r2(chequesNoCobrados),
    cargos_no_registrados: r2(cargosNoRegistrados),
    saldo_banco_ajustado: r2(saldoBancoAjustado),
    saldo_libros_final: r2(saldoLibros),
    diferencia: r2(saldoBancoAjustado - saldoLibros),
  },
};

return [{
  json: {
    job_id,
    resultado_update: {
      estado: 'completado',
      fase_actual: 'ia',
      resultado,
      completed_at: new Date().toISOString(),
    },
  },
}];
